-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the mapping capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: every graded figure(s) printed; section 3 pick A (re-case)
-- advanced: every graded figure(s) printed; section 3 pick A (re-case)
--
-- THE LABEL:
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- mapping / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'mapping' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book mapping refused: mapping/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '811a9e6c7bb042abf1025416aad1ce77' and fields = '[{"key": "n_control_points", "tol": 0, "unit": "count", "label": "Control points used", "expected": 6}, {"key": "grid_nx", "tol": 0, "unit": "nodes", "label": "Grid width", "expected": 25}, {"key": "live_nodes", "tol": 0, "unit": "count", "label": "Mapped (live) grid nodes", "expected": 201}, {"key": "crest_depth_m", "tol": 0.5, "unit": "m", "label": "Crest (shallowest) depth", "expected": 1539.7181396484375}, {"key": "depth_at_p1_m", "tol": 0.5, "unit": "m", "label": "Depth at prospect P-1", "expected": 1542.619873046875}, {"key": "contour_step_m", "tol": 0, "unit": "m", "label": "Contour interval", "expected": 10}]'::jsonb then 'old'
              when md5(prompt) = '88c13b25fa1b403bb725d17ead458a9e' and fields = '[{"key": "n_control_points", "tol": 0, "unit": "count", "label": "Control points used", "expected": 6}, {"key": "grid_nx", "tol": 0, "unit": "nodes", "label": "Grid width", "expected": 25}, {"key": "live_nodes", "tol": 0, "unit": "count", "label": "Mapped (live) grid nodes", "expected": 201}, {"key": "crest_depth_m", "tol": 0.5, "unit": "m", "label": "Crest (shallowest) depth", "expected": 1539.7181396484375}, {"key": "depth_at_p1_m", "tol": 0.5, "unit": "m", "label": "Depth at prospect P-1", "expected": 1542.619873046875}, {"key": "contour_step_m", "tol": 0, "unit": "m", "label": "Contour interval", "expected": 10}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'mapping' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book mapping refused: mapping/beginner matches neither its published form (prompt md5 811a9e6c7bb042abf1025416aad1ce77) nor its W1 form (prompt md5 88c13b25fa1b403bb725d17ead458a9e), with the fields this file was generated against';
  end if;

  -- mapping / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'mapping' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book mapping refused: mapping/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '75cf41e29e7051603053d2fb87bf9474' and fields = '[{"key": "iso_min_m", "tol": 0.1, "unit": "m", "label": "Isochore minimum thickness", "expected": 25}, {"key": "iso_max_m", "tol": 0.1, "unit": "m", "label": "Isochore maximum thickness", "expected": 35.897705078125}, {"key": "iso_mean_m", "tol": 0.1, "unit": "m", "label": "Isochore mean thickness", "expected": 32.25429068038713}, {"key": "iso_at_p1_m", "tol": 0.1, "unit": "m", "label": "Thickness at prospect P-1", "expected": 34.050048828125}, {"key": "iso_nodes_above_well_mean", "tol": 0.0, "unit": "count", "label": "Live isochore nodes above the well mean", "expected": 146.0}, {"key": "mean_well_thickness_m", "tol": 0.05, "unit": "m", "label": "Mean of the six well thicknesses", "expected": 31.166666666666668}]'::jsonb then 'old'
              when md5(prompt) = 'a908fe9a048d40be1e82bcfd451816d3' and fields = '[{"key": "iso_min_m", "tol": 0.1, "unit": "m", "label": "Isochore minimum thickness", "expected": 25}, {"key": "iso_max_m", "tol": 0.1, "unit": "m", "label": "Isochore maximum thickness", "expected": 35.897705078125}, {"key": "iso_mean_m", "tol": 0.1, "unit": "m", "label": "Isochore mean thickness", "expected": 32.25429068038713}, {"key": "iso_at_p1_m", "tol": 0.1, "unit": "m", "label": "Thickness at prospect P-1", "expected": 34.050048828125}, {"key": "iso_nodes_above_well_mean", "tol": 0.0, "unit": "count", "label": "Live isochore nodes above the well mean", "expected": 146.0}, {"key": "mean_well_thickness_m", "tol": 0.05, "unit": "m", "label": "Mean of the six well thicknesses", "expected": 31.166666666666668}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'mapping' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book mapping refused: mapping/intermediate matches neither its published form (prompt md5 75cf41e29e7051603053d2fb87bf9474) nor its W1 form (prompt md5 a908fe9a048d40be1e82bcfd451816d3), with the fields this file was generated against';
  end if;

  -- mapping / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'mapping' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book mapping refused: mapping/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '725fa1ff9551cab456e892f529e76c74' and fields = '[{"key": "cross_validatable_wells", "tol": 0, "unit": "count", "label": "Wells that can be cross-validated", "expected": 1}, {"key": "loo_resid_e6", "tol": 0.1, "unit": "m", "label": "Leave-one-out residual at Ekene-6", "expected": 9.8438720703125}, {"key": "pred_at_e7", "tol": 0.1, "unit": "m", "label": "Six-well grid prediction at Ekene-7", "expected": 1543.3271484375}, {"key": "blind_residual_e7", "tol": 0.1, "unit": "m", "label": "Blind-test residual at Ekene-7", "expected": -5.6728515625}, {"key": "zmin_with_e7", "tol": 0.1, "unit": "m", "label": "Crest depth with Ekene-7 included", "expected": 1540.70556640625}, {"key": "depth_at_p1_with_e7_m", "tol": 0.01, "unit": "m", "label": "Depth at prospect P-1 with Ekene-7 included", "expected": 1547.105224609375}]'::jsonb then 'old'
              when md5(prompt) = 'a7faf6ea15ea17f1aca6dfc26b2decd3' and fields = '[{"key": "cross_validatable_wells", "tol": 0, "unit": "count", "label": "Wells that can be cross-validated", "expected": 1}, {"key": "loo_resid_e6", "tol": 0.1, "unit": "m", "label": "Leave-one-out residual at Ekene-6", "expected": 9.8438720703125}, {"key": "pred_at_e7", "tol": 0.1, "unit": "m", "label": "Six-well grid prediction at Ekene-7", "expected": 1543.3271484375}, {"key": "blind_residual_e7", "tol": 0.1, "unit": "m", "label": "Blind-test residual at Ekene-7", "expected": -5.6728515625}, {"key": "zmin_with_e7", "tol": 0.1, "unit": "m", "label": "Crest depth with Ekene-7 included", "expected": 1540.70556640625}, {"key": "depth_at_p1_with_e7_m", "tol": 0.01, "unit": "m", "label": "Depth at prospect P-1 with Ekene-7 included", "expected": 1547.105224609375}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'mapping' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book mapping refused: mapping/advanced matches neither its published form (prompt md5 725fa1ff9551cab456e892f529e76c74) nor its W1 form (prompt md5 a7faf6ea15ea17f1aca6dfc26b2decd3), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book mapping: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book mapping refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Grid TOP_SAND at the capstone settings (100 m cell) and read the map panel: report the control-point count, the grid width in nodes, how many nodes were mapped, the crest depth, the depth at prospect P-1, and the contour interval the map uses.',
           fields = '[{"key": "n_control_points", "tol": 0, "unit": "count", "label": "Control points used", "expected": 6}, {"key": "grid_nx", "tol": 0, "unit": "nodes", "label": "Grid width", "expected": 25}, {"key": "live_nodes", "tol": 0, "unit": "count", "label": "Mapped (live) grid nodes", "expected": 201}, {"key": "crest_depth_m", "tol": 0.5, "unit": "m", "label": "Crest (shallowest) depth", "expected": 1539.7181396484375}, {"key": "depth_at_p1_m", "tol": 0.5, "unit": "m", "label": "Depth at prospect P-1", "expected": 1542.619873046875}, {"key": "contour_step_m", "tol": 0, "unit": "m", "label": "Contour interval", "expected": 10}]'::jsonb
     where app_slug = 'mapping' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book mapping refused: mapping/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '88c13b25fa1b403bb725d17ead458a9e' and fields = '[{"key": "n_control_points", "tol": 0, "unit": "count", "label": "Control points used", "expected": 6}, {"key": "grid_nx", "tol": 0, "unit": "nodes", "label": "Grid width", "expected": 25}, {"key": "live_nodes", "tol": 0, "unit": "count", "label": "Mapped (live) grid nodes", "expected": 201}, {"key": "crest_depth_m", "tol": 0.5, "unit": "m", "label": "Crest (shallowest) depth", "expected": 1539.7181396484375}, {"key": "depth_at_p1_m", "tol": 0.5, "unit": "m", "label": "Depth at prospect P-1", "expected": 1542.619873046875}, {"key": "contour_step_m", "tol": 0, "unit": "m", "label": "Contour interval", "expected": 10}]'::jsonb) from public.academy_capstones where app_slug = 'mapping' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book mapping refused: mapping/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Grid both SAND surfaces at the capstone settings and subtract them into an isochore. Read the panel: the thickness extremes and mean, the thickness at prospect P-1, how many live isochore nodes sit above the plain mean of the six well thicknesses, and that plain mean itself for comparison.',
           fields = '[{"key": "iso_min_m", "tol": 0.1, "unit": "m", "label": "Isochore minimum thickness", "expected": 25}, {"key": "iso_max_m", "tol": 0.1, "unit": "m", "label": "Isochore maximum thickness", "expected": 35.897705078125}, {"key": "iso_mean_m", "tol": 0.1, "unit": "m", "label": "Isochore mean thickness", "expected": 32.25429068038713}, {"key": "iso_at_p1_m", "tol": 0.1, "unit": "m", "label": "Thickness at prospect P-1", "expected": 34.050048828125}, {"key": "iso_nodes_above_well_mean", "tol": 0.0, "unit": "count", "label": "Live isochore nodes above the well mean", "expected": 146.0}, {"key": "mean_well_thickness_m", "tol": 0.05, "unit": "m", "label": "Mean of the six well thicknesses", "expected": 31.166666666666668}]'::jsonb
     where app_slug = 'mapping' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book mapping refused: mapping/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'a908fe9a048d40be1e82bcfd451816d3' and fields = '[{"key": "iso_min_m", "tol": 0.1, "unit": "m", "label": "Isochore minimum thickness", "expected": 25}, {"key": "iso_max_m", "tol": 0.1, "unit": "m", "label": "Isochore maximum thickness", "expected": 35.897705078125}, {"key": "iso_mean_m", "tol": 0.1, "unit": "m", "label": "Isochore mean thickness", "expected": 32.25429068038713}, {"key": "iso_at_p1_m", "tol": 0.1, "unit": "m", "label": "Thickness at prospect P-1", "expected": 34.050048828125}, {"key": "iso_nodes_above_well_mean", "tol": 0.0, "unit": "count", "label": "Live isochore nodes above the well mean", "expected": 146.0}, {"key": "mean_well_thickness_m", "tol": 0.05, "unit": "m", "label": "Mean of the six well thicknesses", "expected": 31.166666666666668}]'::jsonb) from public.academy_capstones where app_slug = 'mapping' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book mapping refused: mapping/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Cross-validate the TOP_SAND grid by leave-one-out: only wells INSIDE the control hull can be validated (the gridder masks to the hull, so a removed edge well can never see a prediction at its own location). Report how many wells that is and the residual at Ekene-6. Then blind-test the new appraisal well Ekene-7 at (1500, 1500), actual pick 1549 m: the six-well grid prediction there, its residual, and the crest and the depth at prospect P-1 after regridding with Ekene-7 included.',
           fields = '[{"key": "cross_validatable_wells", "tol": 0, "unit": "count", "label": "Wells that can be cross-validated", "expected": 1}, {"key": "loo_resid_e6", "tol": 0.1, "unit": "m", "label": "Leave-one-out residual at Ekene-6", "expected": 9.8438720703125}, {"key": "pred_at_e7", "tol": 0.1, "unit": "m", "label": "Six-well grid prediction at Ekene-7", "expected": 1543.3271484375}, {"key": "blind_residual_e7", "tol": 0.1, "unit": "m", "label": "Blind-test residual at Ekene-7", "expected": -5.6728515625}, {"key": "zmin_with_e7", "tol": 0.1, "unit": "m", "label": "Crest depth with Ekene-7 included", "expected": 1540.70556640625}, {"key": "depth_at_p1_with_e7_m", "tol": 0.01, "unit": "m", "label": "Depth at prospect P-1 with Ekene-7 included", "expected": 1547.105224609375}]'::jsonb
     where app_slug = 'mapping' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book mapping refused: mapping/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'a7faf6ea15ea17f1aca6dfc26b2decd3' and fields = '[{"key": "cross_validatable_wells", "tol": 0, "unit": "count", "label": "Wells that can be cross-validated", "expected": 1}, {"key": "loo_resid_e6", "tol": 0.1, "unit": "m", "label": "Leave-one-out residual at Ekene-6", "expected": 9.8438720703125}, {"key": "pred_at_e7", "tol": 0.1, "unit": "m", "label": "Six-well grid prediction at Ekene-7", "expected": 1543.3271484375}, {"key": "blind_residual_e7", "tol": 0.1, "unit": "m", "label": "Blind-test residual at Ekene-7", "expected": -5.6728515625}, {"key": "zmin_with_e7", "tol": 0.1, "unit": "m", "label": "Crest depth with Ekene-7 included", "expected": 1540.70556640625}, {"key": "depth_at_p1_with_e7_m", "tol": 0.01, "unit": "m", "label": "Depth at prospect P-1 with Ekene-7 included", "expected": 1547.105224609375}]'::jsonb) from public.academy_capstones where app_slug = 'mapping' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book mapping refused: mapping/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book mapping: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
